//the longggg code above is images-sprites and arrays
const int pointsperbg = 1000; //1000 points per bgs
const int runnery =100; //ground line
const int runnerx = 30; //runner horizontal position
const int runnerframeMS = 33; 
const int runnerjumpMS =650;//jump duration in ms
const int runnerjumpheight = 80; //jump height 
const int runnerslideMS = 500; //slide duration in ms
const int runnerflyyheight = 85; //height/change along y while flying
const int flyupppMS = 500; //time to go up while flying
const int flydownnnMS = 500; //time to go down while flying
const int startspeed = 100; //in pixels per secons
const int speedmax =300; //max speed in pixels per second
const int orbheight = 80;
const int gndobstacle =26;
const int slideobstacle =32;
uint32_t runnerscore = 0; //score variable goes to console too
GFXcanvas16 runnercanvas(Screen_Width,Screen_Height);//runner canvas for drawing
uint32_t runnerlastt = 0; //
uint32_t runnertime = 0; //game time
uint32_t runnerscoreMS=0;
int curbg =0; //0->forest,1->city,2->ice castle,3-> alien planet heheh,4-> mysteryy
uint32_t bgstart =0;
int32_t runnermoveleft =0;//leftover player movement
int32_t runnerbgleft =0; //leftover bg movement
int runnerbgscroll= 0; //bg scrolling position
bool runnerjumpnow =false; 
bool runnerslidenow =false; //these change when player suggests action
bool runnerjumpin =false;
bool runnersliding = false; //checks if runner currently jumping or sliding
bool runnerflying = false; //checks if runner flying
bool runnerop = false; //prevents spawn kill after flying
uint32_t jumpstartMS = 0;
uint32_t slidestartMS =0;
uint32_t flystartMS =0;
uint32_t flyMS =0;
int runnerup = 0; 
int runnerflyup =0;//where runner was before flying
bool obstacle = false; //spawns obstacles
int obstaclex = 0; //obstacle x position
int obstacletype = -1; //non defined
uint32_t runnernextobstacleMS = 0; //time to next obstacle
bool orbspawned = false;
bool orbpassed = false; //has orb been passed
int orbx = 0; 
int orbaction = -1; //not decided yet, player has to either jump or roll before it, right action =ord
uint32_t orbspawnat = 0; 
const uint16_t* const runnerbglist[5] = {
 bg0, bg1, bg2, bg3, bg4};
const uint16_t* const runnerRunFrames[3] = {runnerspr_run0,runnerspr_run1,runnerspr_run2};
const uint16_t* const runnerSlideFrames[2] = { runnerspr_slide0, runnerspr_slide1};
const char* const runnerbgNames[5] = {"FOREST","CITY","ALIEN PLANET","FROZEN","MYSTERY"};
uint16_t runneraccent(int b){
    if (b==0) return rgb(59, 50, 240); //forest
    if (b==1) return rgb(110, 18, 230);//city
    if (b==2) return rgb(22, 47, 215);//aliens
    if (b==3) return rgb(0, 255, 255);//frozen
    if (b==4) return rgb(180, 187, 46);//mystery
    return WHITE;}
bool runnercheckcollision(int ax, int ay, int aw,int ah, int bx, int by, int bw, int bh) //checks if two rectangles collide
{ if (ax>=bx+bw) return false;
  if (bx>=ax+aw) return false;
  if (ay>=by+bh) return false;
  if (by>=ay+ah) return false;
  return true;}
void drawsprite(const uint16_t* sprite, int w,int h,int x,int y){ //width height horizontal vertical position
  uint16_t*buf = runnercanvas.getBuffer();//gets pixel buffer
  for (int row =0;row<h;row++){ //loops through all horizontal rows
    int py = y+row; //pixel y 
    if(py<0 or py>=Screen_Height) continue; //if pixel is outta screen, no draw
    for (int col =0;col<w;col++){int px = x+col; //pixel x //goes through each column in a row
      if(px<0 or px>=Screen_Width) continue; //if pixel is out screen, no draw
        uint16_t color_s = sprite[row*w+col]; //gets pixel color of sprite
      if(color_s != RUNNER_KEY) //runner key is meant to be transparent so NOT DRAWNNN
        buf[py*Screen_Width+px] = color_s;}}} //draws pixel to buffer
void runnertext(int x, int y,const char*text,uint8_t size, uint16_t color) { //draws black text (black to be visible)
    runnercanvas. setTextSize(size);//sets text size
    runnercanvas.setTextColor(color);//sets text color
    runnercanvas.setCursor(x,y);//sets text position
    runnercanvas.print(text);} //FINALLY wrires text
void drawbg(){//draws bg
    uint16_t*buf = runnercanvas.getBuffer(); //gets pixel buffer
    const uint16_t*bg = runnerbglist[curbg]; //gets current background
    int full = bgwidth*2; //scales bg properly, img 120*120,screen 240*240
    for (int y = 0; y<Screen_Height;y++){ //loops through all rows
       const uint16_t*row = bg+(y/2)*bgwidth; //gets row of bg //dividng by 2 because bg
       // is half  height of screen
         for (int x = 0; x<Screen_Width;x++){ //loops through all columns
             int imgx = ((x+runnerbgscroll)/2)%full; //gets bg x position, scrolls   
             if (imgx >= bgwidth) imgx = full - 1-imgx; //mirrors img to create continuity
             buf[y*Screen_Width+x] = row[imgx];}}} //draws pixel to buffer
void drawjumpobs(int x){
    int g = runnery; //ground line
    GFXcanvas16&canvas = runnercanvas; //gets canvas
    if (curbg == 1) { // Neon City: three-part barrier
    canvas.fillRect(x,g-24,8,24, rgb(245, 90, 210));
    canvas.fillRect(x + 9, g - 24, 8, 24, rgb(245, 90, 210));
    canvas.fillRect(x + 18, g - 24, 8, 24, rgb(245, 90, 210));}
    else if (curbg == 0) { // Forest: tree stump
    canvas.fillRect(x + 2, g - 18, 22, 18, rgb(95, 62, 45));
    canvas.fillRect(x, g - 22, 26, 6, rgb(130, 90, 60));}
    else if (curbg == 2) { // Desert: broken pillar
    canvas.fillRect(x + 3, g - 20, 20, 20, rgb(110, 85, 160));
    canvas.fillTriangle(x + 3, g - 20, x + 10, g - 27,x + 16, g - 20, rgb(110, 85, 160));} 
    else if (curbg == 3) { // Frozen: three ice spikes
    canvas.fillTriangle(x, g, x + 7, g - 22, x + 13, g,rgb(110, 170, 230));
    canvas.fillTriangle(x + 8, g, x + 15, g - 28, x + 23,g, rgb(155, 220, 255));
    canvas.fillTriangle(x + 16, g, x + 21, g - 18, x + 26, g,rgb(90, 150, 215)); }
     else { // Mystery: three golden spikes
    canvas.fillTriangle(x, g, x + 5, g - 22, x + 10, g,
                        rgb(225, 175, 75));
    canvas.fillTriangle(x + 8, g, x + 13, g - 28, x + 18, g,
                        rgb(240, 195, 95));
    canvas.fillTriangle(x + 16, g, x + 21, g - 22, x + 26, g,
                        rgb(225, 175, 75));}}

void drawslideobs(int x) {
  int g = runnery; // ground line
  GFXcanvas16& canvas = runnercanvas;
  if (curbg == 1) { // Neon City: simple laser 
    canvas.fillRect(x, g - 62, 30, 8, rgb(245, 90, 210)); }
  else if (curbg == 0) { // Forest: branch
    canvas.fillRect(x, g - 60, 32, 8, rgb(100, 70, 48));}
  else if (curbg == 2) { // Desert: floating rock
    canvas.fillRect(x, g - 66, 32, 12, rgb(120, 90, 170));}
  else if (curbg == 3) { // Frozen: one icicle
    canvas.fillTriangle(x, g - 64, x + 30, g - 64,x + 15, g - 28, rgb(155, 220, 255));} 
  else {canvas.fillRect(x, g - 52, 32, 6, rgb(225, 175, 75));// Mystery: hanging bar
  }}
void drawobstacle(){
  if(!obstacle)return; //no obstacle no need to draw anything
  if (obstacletype==1)drawjumpobs(obstaclex);
  else drawslideobs(obstaclex);} //if jump obstacle draws one, else draws slide obstacle
void draworb(){
  if(!orbspawned or orbpassed)return;
  GFXcanvas16&canvas =runnercanvas;
  int x = orbx;
  int y = orbheight;
  canvas.drawCircle(x,y,15,rgb(116, 42, 236));
  canvas.fillCircle (x,y,13,rgb(146, 99, 207));
  canvas.fillCircle(x-4,y-4,3,rgb(184, 173, 220));} //draws an orb then a smol circle for extra shine
int runnerlift =0;
void drawplayer(){
  int feety = runnery-runnerlift; //how far above ground runner is rn
  if (runnerop && !runnerflying && (millis()/80)%2 ==0)return; 
  //if runner is op, not flying the %2 creates a flicker effect since %2 ==0 changes for odd even times
  if (runnerflying){drawsprite(runnerspr_fly, RUNNER_SPR_W,RUNNER_SPR_H,runnerx, feety-RUNNER_SPR_H);}
  //if runner is flying draws flying SPRITE AT RIGHT POSITION 
  else if (runnersliding){int frame =((millis()-slidestartMS)/120)%2;
    drawsprite(runnerSlideFrames[frame],RUNNER_SLIDE_SPR_W,RUNNER_SLIDE_SPR_H,runnerx,feety-RUNNER_SLIDE_SPR_H);}
    //if sliding plays sliding animatuin % switches betwwen frames (slide is 2 frames)
  else if (runnerjumpin){drawsprite(runnerspr_jump,RUNNER_SPR_W,RUNNER_SPR_H,runnerx,feety-RUNNER_SPR_H);}
  //if jumpin draws jumping animation
  //if no jump or slide or fly she runneth sooo
  else{int frame =(runnertime/120)%3; //switches run spr frames every 120 ms
    drawsprite(runnerRunFrames[frame],RUNNER_SPR_W,RUNNER_SPR_H,runnerx, feety-RUNNER_SPR_H);}}
    //draws the sprite
void drawgameinfo(){
  char scoretext[20];
  snprintf(scoretext,sizeof(scoretext),"SCORE%lu",(unsigned long)runnerscore);
  //created variable 20 characters, adds info to it,converts to str with updated info
  runnertext(6,5,scoretext,2,runneraccent(curbg)); //writes scr on canvas
  const char*name = runnerbgNames[curbg];
  //name of bg
  int titlex = Screen_Width -(int)strlen(name)*6 -6;
  // calculates position of name such that it on left from str length as int
  runnertext(titlex,5,name,1,runneraccent(curbg));} //writes text in position
void redraw(){
  drawbg();
  drawgameinfo();
  drawobstacle();
  draworb();
  drawplayer();
  tft.drawRGBBitmap(0,0,runnercanvas.getBuffer(),Screen_Width,Screen_Height);}
  //draws bg first the header then obstacles, then orbs if any then player,updates to screen
  //gets whole fraame FINALLY
bool crash(){
  if (!obstacle or runnerflying)return false;
  int obs;
  if (obstacletype==1){obs =gndobstacle;}
  else {obs = slideobstacle;}
  if (obstaclex >= runnerx+RUNNER_SLIDE_SPR_W-20)return false;
  if (obstaclex+obs <=runnerx)return false; //if obstacle x starts before or after the player's body no crash
  //20 is subtracted cuz the sprites have transparent layer around them
  uint32_t now = millis();
  if (obstacletype==1){if(runnerlift<28)return true;} //if jump obstacle but jump height <28 aka late jump crash
  if (obstacletype==2){uint32_t slidetime = now-slidestartMS;
  if (!runnersliding)return true; //if player is not sliding crashess obvio
  if (slidetime <100)return true; //slide too late still true
  if (slidetime > runnerslideMS -100)return true;}
  return false;} //none of em means no crash 
void gameestart(){
  gameWon =false;
  uint32_t now = millis();
  runnerscore =0;
  runnertime =0;
  runnerlastt= now;
  runnerscoreMS = now;
  bgstart = now;
  flyMS = 0;
  curbg =0;
  runnerbgscroll=0;
  runnerbgleft =0;
  runnerlift =0;
  runnerop = false;
  obstacle =false;
  runnernextobstacleMS =now + random (1200,1800);
  orbspawned= false;
  orbpassed= false;
  orbx =Screen_Width;
  orbspawnat = now + random(5000,10000);
  runnerjumpin=false;
  runnerjumpnow= false;
  runnerslidenow=false;
  runnersliding=false;
  runnerflying=false;
  redraw();} //resets all the variables and booolean values, redraws the whole game 

bool runnerupdate(){
  uint32_t now =millis(); //gets current time
  uint32_t timediff = now-runnerlastt; //time since last change
  if (timediff <runnerframeMS)return true; //if no change in bg nun to update
  runnerlastt =now; //stores current time
  runnertime += timediff; 
  if (now- runnerscoreMS>= 100){ //if score has not been updated
    uint32_t scrno = (now-runnerscoreMS)/100; //adds point for 100 ms survived
    runnerscore += scrno;
    runnerscoreMS += scrno*100;} //updates runenr score ms
    int background = runnerscore /pointsperbg;
    if (background >4)background =4; //after mystery bg it stays mystery bg, no bg change
    if (background !=curbg ){curbg =background; 
      bgstart = now;
      orbspawned = false;
      orbpassed =false; //resets orb
      orbspawnat =now +random (5000,10000);} //new orb in every bg
    if (pressed(Button_A))runnerjumpnow=true;
    if (pressed(Button_B))runnerslidenow =true; //if A jumps B slides
    int speed = startspeed + curbg*20+(int)(runnerscore/5);
    //start speed adds 20 to spped per bg and also 1 to speed every 5 points
    if (speed>speedmax)speed=speedmax; //speed stays below max speads prevents ATTROCIOUSLY FAST gameplay
    runnerbgleft +=(int32_t)speed*(int32_t)timediff;
    //how much bg should move, calculated from speed and time
    int bgstep =runnerbgleft/1000; //no of pixels
    runnerbgleft -=bgstep*1000; //keeps leftover movement for next part
    runnerbgscroll+=bgstep; //moves bg by necessary no of pixels
    if (runnerbgscroll>=bgwidth*4)runnerbgscroll-=bgwidth*4; //resets bg position at end of 2 img scroll area
    runnermoveleft += (int32_t)speed*(int32_t)timediff; //adds movement since prev frame
    int move =(int)runnermoveleft/1000; //converts movement to pixels
    runnermoveleft-=move*1000; //removes part alr moved
    if (runnerjumpin &&now-jumpstartMS>=runnerjumpMS)runnerjumpin =false;
    //if jumping and jump time over player is not jumping anymore
    if (runnersliding && now-slidestartMS>=runnerslideMS)runnersliding =false;
    //if sliding and enough time has passed, not sliding 
    runnerlift =0; //resets vertical height
    if (runnerjumpin){
      uint32_t t =now-jumpstartMS;//how long since jump started
      if (t< (runnerjumpMS/2))runnerlift =(int)
      ((uint32_t)runnerjumpheight*t/(runnerjumpMS/2)); //if player is in first half calculates rising height
      else runnerlift =(int)((uint32_t)runnerjumpheight*(runnerjumpMS-t)/runnerjumpMS/2);}
      //calculates falling height
    if (runnerflying){
      uint32_t t =now-flystartMS;//if flying, how long has player flying
      if (t>=flyMS){runnerflying =false; runnerop =true;}//if fly time over,stops flying, enables op to
      //avoid spawn kill
      else if (t<flyupppMS)
      {runnerlift =(int)((uint32_t)runnerflyyheight*t/flyupppMS);}//height as player goes up
      else if (t>flyMS-flydownnnMS){ //if its time to go down after flying
        runnerlift = (int)((uint32_t)runnerflyyheight*(flyMS-t)/flydownnnMS);} //height as player down
      else{ //if not going up or coming down or landing flying rn
        runnerlift =runnerflyyheight;}}
    if (runnerop &&now-(flystartMS+flyMS)>=400)runnerop=false; //if op and 400 ms has passed, not op more
    bool ongrnd = !runnerjumpin && !runnersliding && !runnerflying;
    //if not jumping or running or flying on ground
    if (ongrnd && runnerjumpnow){
      runnerjumpin=true;
      jumpstartMS =now;} //can only jump on grnd, starts jump, records time
    if (ongrnd && runnerslidenow){
      runnersliding=true; slidestartMS =now;} //only side on grnd, starts and records time
    if (!orbspawned &&(int32_t)(now-orbspawnat)>=0){ //if no orb spawned and time for it
       orbspawned=true;orbpassed=false; //sets orb spawned as true, not collected yet cuz it just spanw
       orbx =Screen_Width+10; //places it
       if (random(0,2)==0){orbaction=1;} //decides random action
       else{orbaction=2;};}
    if (orbspawned && !orbpassed){ //there an orb but it no collected yet
      orbx-=move; //moves orb accordingly(movement)
      bool near =(orbx>=runnerx-12) &&(orbx <= runnerx+ RUNNER_SPR_W+12);
      //if ord near player
      if (near && (runnerjumpnow or runnerslidenow)){
        orbpassed =true; //orb has passed player do sumn
        bool right = false;
        if (orbaction ==1){right=runnerjumpnow;}
        else{right=runnerslidenow;} // creates a bool called right and checks
        if (right){
          runnerflying = true;flystartMS = now;flyMS=flyupppMS +1200+flydownnnMS;
          runnerjumpin=false;runnersliding=false;}} //if player chose right, flying starts, earlier jump or slide
          //disabled
        if (orbx<runnerx-15)orbpassed=true;} //if orb passed marks it collected 
  runnerjumpnow=false;
  runnerslidenow=false; //resets every frame
  if (!obstacle &&(int32_t)(now-runnernextobstacleMS)>=0){ //if no curr obstacle and time for next one
    obstacle = true;
    obstaclex= Screen_Width; //makrs obstacle as treu (aka it there)places on right
    if (random(0,2)==0){obstacletype =1;}
    else{obstacletype=2;}} //randomly picks an obstacle type
  if(obstacle){
    obstaclex -=move;
    if(obstaclex<-slideobstacle-4){
      obstacle =false;
      runnernextobstacleMS =now+random(1000,2000);}} //if off screen then removes and finds next obs when
  if (!runnerop &&crash()){
    redraw();
    return false;} //if runner not safe and hits then draws final frame and returns false to end game
  redraw();//draws current frame
  return true;} //true cuz game still running
//THE ENDDDDD



    





  












   